diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 761f866..8a55ddd 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1993,6 +1993,76 @@ extern "C" void c_cedebug(natl id, const char *buf, natq quanti)
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+extern "C" void c_driver_ce(natl id)
+{
+	des_ce *ce = &array_ce[id];
+	if (!ce->enabled)
+		return;
+	
+	natb byte = inputb(ce->iRBR);
+	*ce->buf++ = byte;
+	ce->quanti--;
+	sem_signal(ce->sync);
+}
+
+extern "C" bool c_ceread_n_to(natl id, char *buf, natq& quanti, natl to)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceread_n_to: dispositivo non valido: %u", id);
+		c_abort_p();
+		return false;
+	}
+	
+	if (!to) {
+		flog(LOG_WARN, "ceread_n_to: timeout nullo");
+		c_abort_p();
+		return false;
+	}
+	
+	if (liv_chiamante() == LIV_UTENTE) {
+		if (!c_access(int_cast<vaddr>(buf), quanti, false, false)) {
+			flog(LOG_WARN, "ceread_n_to: buffer non valido");
+			c_abort_p();
+			return false;
+		}
+		if (!c_access(int_cast<vaddr>(&quanti), sizeof(natq), true, false)) {
+			flog(LOG_WARN, "ceread_n_to: quanti non valido");
+			c_abort_p();
+			return false;
+		}
+	}
+	
+	des_ce *ce = &array_ce[id];
+	c_sem_wait(ce->mutex);
+	
+	ce->enabled = true;
+	ce->buf = buf;
+	ce->quanti = quanti;
+	outputb(1, ce->iCTL);
+	
+	natl bytes_read = 0;
+	bool success = true;
+	
+	while (ce->quanti > 0) {
+		c_sem_wait_to(ce->sync, to);
+		natl rem = esecuzione->contesto[I_RAX];
+		if (rem == 0) {
+			success = false;
+			break;
+		}
+		to = rem;
+		bytes_read++;
+	}
+	
+	outputb(0, ce->iCTL);
+	ce->enabled = false;
+	quanti = bytes_read;
+	c_sem_signal(ce->mutex);
+	
+	return success;
+}
+
 //   SOLUZIONE 2024-01-10 )

